use super::{KnowledgeChunkId, KnowledgeSource, KnowledgeSourceId, SourceOrigin};
use crate::models::file::FileId;
use crate::models::shared::{
    AccountId, DomainError, DomainResult, ensure_same_account, require_non_blank,
};

/// Source-relative location, not an offset in an answer generated by a model.
#[derive(Clone, Debug, PartialEq)]
pub enum SourceLocator {
    WholeSource,
    /// One-based page number in the original PDF.
    PdfPage {
        page: u32,
    },
    /// Zero-based, half-open Unicode character range in the source text.
    TextRange {
        start: u64,
        end: u64,
    },
    DocumentBlock {
        block_id: String,
    },
    /// Normalized source-image coordinates, with origin at its top-left.
    ImageRegion {
        x: f64,
        y: f64,
        width: f64,
        height: f64,
    },
    /// Half-open millisecond interval in the original audio or video.
    TimeRange {
        start_ms: u64,
        end_ms: u64,
    },
}

impl SourceLocator {
    pub fn validate(&self) -> DomainResult<()> {
        let valid = match self {
            Self::WholeSource => true,
            Self::PdfPage { page } => *page > 0,
            Self::TextRange { start, end } => start < end,
            Self::DocumentBlock { block_id } => {
                return require_non_blank("block_id", block_id);
            }
            Self::ImageRegion {
                x,
                y,
                width,
                height,
            } => {
                [x, y, width, height].iter().all(|value| value.is_finite())
                    && *x >= 0.0
                    && *y >= 0.0
                    && *width > 0.0
                    && *height > 0.0
                    && x + width <= 1.0
                    && y + height <= 1.0
            }
            Self::TimeRange { start_ms, end_ms } => start_ms < end_ms,
        };
        if !valid {
            return Err(DomainError::InvalidValue {
                field: "locator",
                reason: "source location is empty or outside its valid range",
            });
        }
        Ok(())
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct KnowledgeChunk {
    id: KnowledgeChunkId,
    account_id: AccountId,
    source_id: KnowledgeSourceId,
    ordinal: u32,
    text: String,
    locator: SourceLocator,
    index_version: String,
}

impl KnowledgeChunk {
    /// `index_version` identifies the parser/chunker/embedding recipe. Changing
    /// that recipe produces new chunks rather than overwriting cited evidence.
    pub fn new(
        id: KnowledgeChunkId,
        source: &KnowledgeSource,
        ordinal: u32,
        text: impl Into<String>,
        locator: SourceLocator,
        index_version: impl Into<String>,
    ) -> DomainResult<Self> {
        let text = text.into();
        let index_version = index_version.into();
        require_non_blank("text", &text)?;
        require_non_blank("index_version", &index_version)?;
        locator.validate()?;
        Ok(Self {
            id,
            account_id: source.account_id(),
            source_id: source.id(),
            ordinal,
            text,
            locator,
            index_version,
        })
    }

    pub fn citation(&self, source: &KnowledgeSource) -> DomainResult<SourceCitation> {
        ensure_same_account(self.account_id, source.account_id())?;
        if self.source_id != source.id() {
            return Err(DomainError::RevisionMismatch);
        }
        Ok(SourceCitation {
            chunk_id: self.id,
            source_id: self.source_id,
            title: source.title().to_owned(),
            origin: source.origin().clone(),
            original_file_id: source.original_file_id(),
            locator: self.locator.clone(),
        })
    }

    pub fn id(&self) -> KnowledgeChunkId {
        self.id
    }
    pub fn account_id(&self) -> AccountId {
        self.account_id
    }
    pub fn source_id(&self) -> KnowledgeSourceId {
        self.source_id
    }
    pub fn ordinal(&self) -> u32 {
        self.ordinal
    }
    pub fn text(&self) -> &str {
        &self.text
    }
    pub fn locator(&self) -> &SourceLocator {
        &self.locator
    }
    pub fn index_version(&self) -> &str {
        &self.index_version
    }
}

/// Resolved provenance. Download URLs are generated by an authorized delivery
/// layer; transient signed URLs never become the identity of the source.
#[derive(Clone, Debug, PartialEq)]
pub struct SourceCitation {
    chunk_id: KnowledgeChunkId,
    source_id: KnowledgeSourceId,
    title: String,
    origin: SourceOrigin,
    original_file_id: Option<FileId>,
    locator: SourceLocator,
}

impl SourceCitation {
    pub fn chunk_id(&self) -> KnowledgeChunkId {
        self.chunk_id
    }
    pub fn source_id(&self) -> KnowledgeSourceId {
        self.source_id
    }
    pub fn title(&self) -> &str {
        &self.title
    }
    pub fn origin(&self) -> &SourceOrigin {
        &self.origin
    }
    pub fn original_file_id(&self) -> Option<FileId> {
        self.original_file_id
    }
    pub fn locator(&self) -> &SourceLocator {
        &self.locator
    }
}
